CREATE TABLE iot_site (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,workshop VARCHAR(60) NOT NULL,planned_capacity INT NOT NULL,active BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE iot_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(50) NOT NULL,role VARCHAR(20) NOT NULL,site_code VARCHAR(32),enabled BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE iot_device_task (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(32) NOT NULL UNIQUE,product_code VARCHAR(40) NOT NULL,product_name VARCHAR(120) NOT NULL,site_id BIGINT NOT NULL,planned_qty INT NOT NULL,completed_qty INT NOT NULL,defect_qty INT NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,batch_no VARCHAR(40),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_order_center FOREIGN KEY(site_id) REFERENCES iot_site(id));
CREATE TABLE iot_telemetry_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,device_task_id BIGINT NOT NULL,operation_name VARCHAR(50) NOT NULL,good_qty INT NOT NULL,defect_qty INT NOT NULL,operator_name VARCHAR(50) NOT NULL,reported_at DATETIME(6) NOT NULL,remark VARCHAR(200),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_report_order FOREIGN KEY(device_task_id) REFERENCES iot_device_task(id));
CREATE TABLE iot_alarm_event (id BIGINT AUTO_INCREMENT PRIMARY KEY,alarm_event_no VARCHAR(32) NOT NULL UNIQUE,device_task_id BIGINT NOT NULL,alarm_event_type VARCHAR(30) NOT NULL,sample_qty INT NOT NULL,defect_qty INT NOT NULL,result VARCHAR(20) NOT NULL,inspector VARCHAR(50),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_inspection_order FOREIGN KEY(device_task_id) REFERENCES iot_device_task(id));
CREATE TABLE iot_device (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,site_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,oee INT NOT NULL,last_heartbeat DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_equipment_center FOREIGN KEY(site_id) REFERENCES iot_site(id));
CREATE INDEX idx_order_status_due ON iot_device_task(status,due_date); CREATE INDEX idx_report_order_time ON iot_telemetry_record(device_task_id,reported_at); CREATE INDEX idx_equipment_status ON iot_device(status);
